-- API roles must fail BEFORE RLS, for same and foreign orgs and spoofed claims.
DO $acl$
DECLARE r text; subj text; claim_org text; p jsonb; blocked boolean; count_tests int:=0;
BEGIN
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  FOREACH subj IN ARRAY ARRAY[current_setting('mesh_stage4.user_a'),current_setting('mesh_stage4.user_b')] LOOP
   FOREACH claim_org IN ARRAY ARRAY['44444444-4444-4444-8444-000000000001','44444444-4444-4444-8444-000000000002'] LOOP
    PERFORM set_config('request.jwt.claim.sub',subj,true);
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',subj,'organization_id',claim_org,'user_metadata',jsonb_build_object('organization_id',claim_org,'role','security_team'))::text,true);
    FOR p IN SELECT value FROM jsonb_array_elements($cases$[{"table": "security_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "SELECT", "sql": "SELECT organization_id FROM public.security_events WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "INSERT", "sql": "INSERT INTO public.security_events (organization_id,source,event_type,event_time) VALUES ('44444444-4444-4444-8444-000000000001','stage4-denied','login','2026-01-01T00:00:00Z')"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "UPDATE", "sql": "UPDATE public.security_events SET organization_id=organization_id WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "DELETE", "sql": "DELETE FROM public.security_events WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "SELECT", "sql": "SELECT organization_id FROM public.security_events WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "INSERT", "sql": "INSERT INTO public.security_events (organization_id,source,event_type,event_time) VALUES ('44444444-4444-4444-8444-000000000002','stage4-denied','login','2026-01-01T00:00:00Z')"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "UPDATE", "sql": "UPDATE public.security_events SET organization_id=organization_id WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "security_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "DELETE", "sql": "DELETE FROM public.security_events WHERE organization_id='44444