ident_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "SELECT", "sql": "SELECT organization_id FROM public.incident_events WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "INSERT", "sql": "INSERT INTO public.incident_events (organization_id,incident_id,event_id) VALUES ('44444444-4444-4444-8444-000000000001','44444444-4444-4444-8444-000000000016','44444444-4444-4444-8444-000000000012')"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "UPDATE", "sql": "UPDATE public.incident_events SET organization_id=organization_id WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000001", "operation": "DELETE", "sql": "DELETE FROM public.incident_events WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "SELECT", "sql": "SELECT organization_id FROM public.incident_events WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "INSERT", "sql": "INSERT INTO public.incident_events (organization_id,incident_id,event_id) VALUES ('44444444-4444-4444-8444-000000000002','44444444-4444-4444-8444-000000000016','44444444-4444-4444-8444-000000000012')"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "UPDATE", "sql": "UPDATE public.incident_events SET organization_id=organization_id WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "incident_events", "organization": "44444444-4444-4444-8444-000000000002", "operation": "DELETE", "sql": "DELETE FROM public.incident_events WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000001", "operation": "SELECT", "sql": "SELECT organization_id FROM public.security_risk_scores WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000001", "operation": "INSERT", "sql": "INSERT INTO public.security_risk_scores (organization_id,subject_type,subject_id,score,model_version) VALUES ('44444444-4444-4444-8444-000000000001','finding','44444444-4444-4444-8444-000000000014',1,'stage4-denied')"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000001", "operation": "UPDATE", "sql": "UPDATE public.security_risk_scores SET organization_id=organization_id WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000001", "operation": "DELETE", "sql": "DELETE FROM public.security_risk_scores WHERE organization_id='44444444-4444-4444-8444-000000000001'"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000002", "operation": "SELECT", "sql": "SELECT organization_id FROM public.security_risk_scores WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000002", "operation": "INSERT", "sql": "INSERT INTO public.security_risk_scores (organization_id,subject_type,subject_id,score,model_version) VALUES ('44444444-4444-4444-8444-000000000002','finding','44444444-4444-4444-8444-000000000014',1,'stage4-denied')"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000002", "operation": "UPDATE", "sql": "UPDATE public.security_risk_scores SET organization_id=organization_id WHERE organization_id='44444444-4444-4444-8444-000000000002'"}, {"table": "security_risk_scores", "organization": "44444444-4444-4444-8444-000000000002", "operation": "DELETE", "sql": "DELETE FROM public.security_risk_scores WHERE organization_id='44444444-4444-4444-8444-000000000002'"}]$cases$::jsonb) LOOP
     blocked:=false;
     BEGIN
      EXECUTE format('SET LOCAL ROLE %I',r);
      EXECUTE (p->>'sql');
      RESET ROLE;
     EXCEPTION WHEN insufficient_privilege THEN blocked:=true;
     END;
     IF NOT blocked THEN RAISE EXCEPTION 'Unexpected API access role %, table %, op %',r,p->>'table',p->>'operation'; END IF;
     count_tests:=count_tests+1;
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP;
 IF count_tests<>480 THEN RAISE EXCEPTION 'Incomplete ACL probes'; END IF;
 PERFORM set_config('mesh_stage4.acl_tests',count_tests::text,true);
END $acl$;
